"""Mechanical export/QA only; no painting is generated by this script."""
import json
import sys
from pathlib import Path
from PIL import Image, ImageDraw, ImageStat

OUT = Path(__file__).parent

def preview(bg, width, height):
    # Current desktop game is a centred portrait frame, max-width 480px.
    vw, vh = min(width, 480), height
    fx, fy, fw, fh = 6, 152, vw - 12, vh - 390
    ax, ay = fx + fw / 2, fy + fh * .27
    scale = max(fw/1536, fh/768, ax/768, (vw-ax)/768,
                ay/(1024*.45), (vh-ay)/(1024*.55))
    bw, bh = 1536*scale, 1024*scale
    bx, by = ax-bw/2, ay-bh*.45
    frame = bg.transform((vw, vh), Image.Transform.AFFINE,
                         (1/scale, 0, -bx/scale, 0, 1/scale, -by/scale),
                         Image.Resampling.BICUBIC)
    # Match continuous-scene HUD dimming, without inventing game UI.
    shade = Image.new('RGBA', frame.size)
    sd = ImageDraw.Draw(shade)
    stops = [(0,.75),(.22,0),(.52,0),(.74,.70),(1,.90)]
    for y in range(vh):
        p = y/vh
        for (a,aa),(b,bb) in zip(stops,stops[1:]):
            if a <= p <= b:
                alpha = aa + (bb-aa)*(p-a)/(b-a)
                break
        sd.line((0,y,vw,y), fill=(5,11,20,int(alpha*255)))
    frame = Image.alpha_composite(frame.convert('RGBA'), shade).convert('RGB')
    d = ImageDraw.Draw(frame)
    # Eight-actor stress test: current six-slot layout plus mirrored enemy front pair.
    top, gap, panel = min(70,fh*.13),16,50
    rh = (fh-top-gap-4)/2
    for enemy in (False,True):
        for front in (False,True):
            for row in (0,1):
                x = fx + fw*((.80 if not front else .60) if enemy else (.405 if front else .145))
                y = fy + top + row*(rh+gap)+rh-panel+(3 if front else 0)-5
                size = max(44,min(100,fw*.24-8,rh-panel-8))
                color = '#d9cbea' if enemy else '#d0e5e3'
                ink = '#292335' if enemy else '#1c3038'
                # Neutral facing bust, torso and split legs; feet anchored at y.
                s=size
                d.ellipse((x-s*.13,y-s*.96,x+s*.13,y-s*.70),fill=ink,outline=color,width=2)
                face = -1 if enemy else 1
                d.polygon([(x+face*s*.11,y-s*.87),(x+face*s*.21,y-s*.82),(x+face*s*.11,y-s*.79)],fill=color)
                d.polygon([(x-s*.22,y-s*.69),(x+s*.22,y-s*.69),(x+s*.17,y-s*.30),(x+s*.08,y-2),(x+2,y-2),(x,y-s*.28),(x-2,y-2),(x-s*.13,y-2),(x-s*.18,y-s*.30)],fill=ink,outline=color,width=2)
                ring = '#b59aff' if enemy else '#74d4ef'
                d.ellipse((x-s*.34,y-3,x+s*.34,y+7),outline=ring,width=2)
                d.rectangle((x-s*.31,y+17,x+s*.31,y+24),fill='#08121d',outline='#d8e6ed')
                d.rectangle((x-s*.29,y+19,x+s*.18,y+22),fill=ring)
    canvas=Image.new('RGB',(width,height),'#080e19')
    canvas.paste(frame,((width-vw)//2,0))
    return canvas,dict(view=[vw,vh],field=[fx,fy,fw,fh],backdrop=[bx,by,bw,bh],horizon=ay)

if __name__ == '__main__':
    report={}
    for name, source in zip(('forest','riftline'),sys.argv[1:]):
        bg=Image.open(source).convert('RGB')
        assert bg.size==(1536,1024),bg.size
        dest=OUT/f'bg_{name}.webp'
        bg.save(dest,'WEBP',quality=94,method=6)
        bg=Image.open(dest).convert('RGB')
        report[name]={'size':list(bg.size),'mode':bg.mode,'opaque':True,'bytes':dest.stat().st_size,'previews':{}}
        for w,h in ((390,844),(1366,768)):
            im,geometry=preview(bg,w,h)
            im.save(OUT/f'preview_{name}_{w}x{h}.png')
            report[name]['previews'][f'{w}x{h}']=geometry
    (OUT/'validation.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps(report,indent=2))
